package com.clavis.reader;
import android.content.Context;import android.util.Xml;import org.xmlpull.v1.XmlPullParser;import org.json.*;import java.io.*;import java.net.*;import java.util.*;
/** Bounded RSS/Atom subscriptions, cached independently from the book library. */
final class FeedStore {
 static boolean category(String kind){return kind.equals("News")||kind.equals("Podcasts")||kind.equals("Journals");}
 static final class Item {
  String id="",title="",link="",description="",image="",audio="",document="",date="";long duration;
  JSONObject json()throws Exception{return new JSONObject().put("id",id).put("title",title).put("link",link).put("description",description).put("image",image).put("audio",audio).put("document",document).put("date",date).put("duration",duration);}
  static Item from(JSONObject j){Item i=new Item();i.id=j.optString("id");i.title=j.optString("title");i.link=j.optString("link");i.description=j.optString("description");i.image=j.optString("image");i.audio=j.optString("audio");i.document=j.optString("document");i.date=j.optString("date");i.duration=j.optLong("duration");return i;}
 }
 static final class Feed {
  final IdentityHashMap<Item,Feed> origins=new IdentityHashMap<>();
  String url="",kind="",title="",image="",error="";long updated;ArrayList<Item> items=new ArrayList<>();
  JSONObject json()throws Exception{JSONArray list=new JSONArray();for(Item i:items)list.put(i.json());return new JSONObject().put("url",url).put("kind",kind).put("title",title).put("image",image).put("updated",updated).put("error",error).put("items",list);}
 }
 static synchronized ArrayList<Feed> load(Context c){ArrayList<Feed> list=new ArrayList<>();try{JSONArray data=new JSONArray(c.getSharedPreferences("rss_feeds",0).getString("feeds","[]"));for(int n=0;n<data.length();n++){JSONObject j=data.getJSONObject(n);Feed f=new Feed();f.url=j.optString("url");f.kind=j.optString("kind");f.title=j.optString("title");f.image=j.optString("image");f.error=j.optString("error");f.updated=j.optLong("updated");JSONArray items=j.optJSONArray("items");if(items!=null)for(int x=0;x<items.length();x++)f.items.add(Item.from(items.getJSONObject(x)));list.add(f);}}catch(Exception ignored){}return list;}
 static synchronized void put(Context c,Feed feed){ArrayList<Feed> list=load(c);list.removeIf(f->f.url.equals(feed.url)&&f.kind.equals(feed.kind));list.add(feed);save(c,list);}
 static synchronized void remove(Context c,Feed feed){ArrayList<Feed> list=load(c);list.removeIf(f->f.url.equals(feed.url)&&f.kind.equals(feed.kind));save(c,list);}
 static void save(Context c,ArrayList<Feed> list){JSONArray data=new JSONArray();try{for(Feed f:list)data.put(f.json());}catch(Exception e){throw new IllegalStateException(e);}c.getSharedPreferences("rss_feeds",0).edit().putString("feeds",data.toString()).apply();}
 static String web(String value){try{URI u=new URI(value.trim());if(("https".equalsIgnoreCase(u.getScheme())||"http".equalsIgnoreCase(u.getScheme()))&&u.getHost()!=null)return u.toASCIIString();}catch(Exception ignored){}return "";}
 static String resolve(String base,String value){try{return web(new URI(base).resolve(value.trim()).toString());}catch(Exception e){return "";}}
 static HttpURLConnection connect(String url)throws Exception{return connect(url,15000,20000);}
 static HttpURLConnection connect(String url,int connectTimeout,int readTimeout)throws Exception{String current=web(url);for(int redirects=0;redirects<6;redirects++){if(!current.startsWith("https://"))throw new IOException("Use an HTTPS feed URL");HttpURLConnection c=(HttpURLConnection)new URL(current).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(connectTimeout);c.setReadTimeout(readTimeout);c.setRequestProperty("User-Agent","Clavis/0.7 RSS Reader");c.setRequestProperty("Accept","application/rss+xml, application/atom+xml, application/xml, text/xml, */*");try{int status=c.getResponseCode();if(status>=300&&status<400){current=resolve(current,c.getHeaderField("Location"));c.disconnect();continue;}if(status<200||status>=300)throw new IOException("Server returned HTTP "+status);return c;}catch(Exception e){c.disconnect();throw e;}}throw new IOException("Too many feed redirects");}
 static byte[] fetch(String url,int max)throws Exception{HttpURLConnection c=connect(url);try{if(c.getContentLengthLong()>max)throw new IOException("Feed resource is too large");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1){if(out.size()+n>max)throw new IOException("Feed resource is too large");out.write(b,0,n);}return out.toByteArray();}}finally{c.disconnect();}}
 static Feed download(String url,String kind)throws Exception{HttpURLConnection connection=connect(url);try(InputStream stream=new BufferedInputStream(connection.getInputStream());InputStream limited=new FilterInputStream(stream){long count;void consumed(int n)throws IOException{if(n>0&&(count+=n)>8*1024*1024)throw new IOException("Feed resource is too large");}public int read()throws IOException{int value=in.read();consumed(value<0?0:1);return value;}public int read(byte[] b,int off,int len)throws IOException{int n=in.read(b,off,len);consumed(n);return n;}}){Feed feed=parse(limited,connection.getURL().toString());feed.url=web(url);feed.kind=kind;feed.updated=System.currentTimeMillis();return feed;}finally{connection.disconnect();}}
 static String attr(XmlPullParser p,String key){for(int i=0;i<p.getAttributeCount();i++)if(key.equalsIgnoreCase(p.getAttributeName(i)))return p.getAttributeValue(i);return "";}
 static long duration(String value){try{String[] parts=value.trim().split(":");double seconds=0;for(String part:parts)seconds=seconds*60+Double.parseDouble(part);return Math.max(0,(long)(seconds*1000));}catch(Exception e){return 0;}}
 static Feed parse(InputStream stream,String url)throws Exception{
  Feed feed=new Feed();feed.url=web(url);XmlPullParser p=Xml.newPullParser();p.setFeature(XmlPullParser.FEATURE_PROCESS_NAMESPACES,true);p.setInput(stream,null);Item item=null;int itemDepth=-1;boolean recognized=false;HashSet<String> ids=new HashSet<>();
  for(int event=p.next();event!=XmlPullParser.END_DOCUMENT;event=p.next()){
   if(event==XmlPullParser.DOCDECL)throw new IOException("Unsupported feed declaration");
   if(event==XmlPullParser.START_TAG){String tag=p.getName().toLowerCase(Locale.ROOT),ns=p.getNamespace()==null?"":p.getNamespace();int depth=p.getDepth();
    if(tag.equals("rss")||tag.equals("feed")||tag.equals("rdf"))recognized=true;
    if(tag.equals("item")||tag.equals("entry")){item=new Item();itemDepth=depth;continue;}
    if(tag.equals("enclosure")||tag.equals("content")&&ns.contains("search.yahoo.com/mrss")||tag.equals("link")&&attr(p,"rel").equals("enclosure")){
     if(item!=null){String media=resolve(url,!attr(p,"url").isEmpty()?attr(p,"url"):attr(p,"href")),type=attr(p,"type");if(type.startsWith("audio/")||media.toLowerCase(Locale.ROOT).matches(".*\\.(mp3|m4a|m4b|ogg|opus|wav)(\\?.*)?$"))item.audio=media;else if(type.equals("application/pdf"))item.document=media;else if(type.startsWith("image/"))item.image=media;}continue;
    }
    if(tag.equals("thumbnail")||tag.equals("image")&&!attr(p,"href").isEmpty()){String image=resolve(url,tag.equals("thumbnail")?attr(p,"url"):attr(p,"href"));if(item==null)feed.image=image;else item.image=image;continue;}
    if(tag.equals("link")&&!attr(p,"href").isEmpty()){if(item!=null&&(attr(p,"rel").isEmpty()||attr(p,"rel").equals("alternate")))item.link=resolve(url,attr(p,"href"));continue;}
    boolean direct=item!=null?depth==itemDepth+1:depth==2||depth==3;
    if(direct&&(tag.equals("title")||tag.equals("link")||tag.equals("description")||tag.equals("encoded")||tag.equals("summary")||tag.equals("content")||tag.equals("guid")||tag.equals("id")||tag.equals("date")||tag.equals("coverdate")||tag.equals("publicationdate")||tag.equals("pubdate")||tag.equals("published")||tag.equals("updated")||tag.equals("duration"))){String value=readText(p);if(item==null){if(tag.equals("title"))feed.title=value;}else switch(tag){case "title":item.title=value;break;case "link":item.link=resolve(url,value);break;case "description":case "summary":if(item.description.isEmpty())item.description=value;break;case "encoded":case "content":if(value.length()>item.description.length())item.description=value;break;case "guid":case "id":item.id=value;break;case "date":case "coverdate":case "publicationdate":case "pubdate":case "published":if(item.date.isEmpty())item.date=value;break;case "updated":if(item.date.isEmpty())item.date=value;break;case "duration":item.duration=duration(value);break;}continue;}
    if((tag.equals("logo")||tag.equals("icon"))&&item==null){feed.image=resolve(url,readText(p));continue;}
    if(tag.equals("url")&&item==null&&feed.image.isEmpty())feed.image=resolve(url,readText(p));
   }else if(event==XmlPullParser.END_TAG&&item!=null&&p.getDepth()==itemDepth){if(item.title.isEmpty())item.title="Untitled entry";if(item.id.isEmpty())item.id=!item.audio.isEmpty()?item.audio:!item.link.isEmpty()?item.link:item.title+item.date;if(ids.add(item.id)&&feed.items.size()<300)feed.items.add(item);item=null;if(feed.items.size()>=300)break;}
  }
  if(!recognized)throw new IOException("This URL is not an RSS or Atom feed. Paste the feed URL rather than the website address.");if(feed.title.isEmpty())feed.title=new URI(url).getHost();for(Item i:feed.items){if(i.image.isEmpty()){java.util.regex.Matcher image=java.util.regex.Pattern.compile("(?is)<img[^>]+src=[\"']([^\"']+)").matcher(i.description);if(image.find())i.image=resolve(url,image.group(1));}if(i.image.isEmpty())i.image=feed.image;}return feed;
 }
 static String readText(XmlPullParser p)throws Exception{int start=p.getDepth();StringBuilder out=new StringBuilder();for(int e=p.next();!(e==XmlPullParser.END_TAG&&p.getDepth()==start);e=p.next()){if(e==XmlPullParser.END_DOCUMENT)break;if(e==XmlPullParser.TEXT||e==XmlPullParser.CDSECT||e==XmlPullParser.ENTITY_REF)out.append(p.getText());else if(e==XmlPullParser.START_TAG)out.append(' ');if(out.length()>1024*1024)throw new IOException("Feed entry too large");}return out.toString().trim();}
 static final java.util.concurrent.ConcurrentHashMap<String,Object> imageLocks=new java.util.concurrent.ConcurrentHashMap<>();
 static File image(Context c,String url)throws Exception{if(url.startsWith("http://"))url="https://"+url.substring(7);if(web(url).isEmpty())return null;String key=url;Object lock=imageLocks.computeIfAbsent(key,k->new Object());synchronized(lock){return cachedImage(c,key);}}
 static File cachedImage(Context c,String url)throws Exception{File dir=new File(c.getCacheDir(),"rss-artwork");dir.mkdirs();StringBuilder digest=new StringBuilder();for(byte b:java.security.MessageDigest.getInstance("SHA-256").digest(url.getBytes(java.nio.charset.StandardCharsets.UTF_8)))digest.append(String.format(Locale.US,"%02x",b&255));File file=new File(dir,digest+".img");if(!file.isFile()){HttpURLConnection connection=connect(url,6000,8000);File tmp=File.createTempFile("rss-",".tmp",dir);try{if(connection.getContentLengthLong()>5*1024*1024)throw new IOException("Artwork too large");try(InputStream in=connection.getInputStream();OutputStream out=new FileOutputStream(tmp)){byte[] buffer=new byte[16384];int n,total=0;while((n=in.read(buffer))!=-1){total+=n;if(total>5*1024*1024)throw new IOException("Artwork too large");out.write(buffer,0,n);}}if(!tmp.renameTo(file)&&!file.exists())throw new IOException("Cannot cache artwork");}finally{connection.disconnect();tmp.delete();}}return file;}
}


